local terminal = "kitty"
local fileManager = "nautilus"
local menu = "hyprlauncher"
local browser = "google-chrome-stable"
local noctalia = "noctalia"
local noctalia_ipc = noctalia .. " msg "

---------------------
--- GLOBAL STATES ---
---------------------

local MAX_ZOOM = 3.0
local MIN_ZOOM = 1.0
local is_zoomed = false

---------------------
---- HELPER FUNCTIONS ----
---------------------

local function set_zoom(offset)
    local current = hl.get_config("cursor.zoom_factor") or 1.0
    local new_zoom = 1.0

    if offset then
        new_zoom = math.min(MIN_ZOOM + MAX_ZOOM - 1.0, math.max(MIN_ZOOM, current + offset))
    end

    is_zoomed = new_zoom > 1.0

    hl.config({
        cursor = {
            zoom_factor = new_zoom,
        },
    })
end

