--------------------------------------------------------------------------------
-- ANIMATION CONFIGURATION
--------------------------------------------------------------------------------

local speed_fast = 3.0
local speed_normal = 4.5
local speed_slow = 5.0
local speed_out = 4.5

--------------------------------------------------------------------------------
-- CURVES
--------------------------------------------------------------------------------

-- Smooth and clean
hl.curve("smooth", {
    type = "bezier",
    points = {
        { 0.22, 1.0 },
        { 0.36, 1.0 },
    },
})

-- Fast acceleration with soft landing
hl.curve("smoothOut", {
    type = "bezier",
    points = {
        { 0.16, 1.0 },
        { 0.30, 1.0 },
    },
})

-- Soft fade
hl.curve("soft", {
    type = "bezier",
    points = {
        { 0.25, 0.1 },
        { 0.25, 1.0 },
    },
})

-- Very fast
hl.curve("quick", {
    type = "bezier",
    points = {
        { 0.15, 0.0 },
        { 0.10, 1.0 },
    },
})

--------------------------------------------------------------------------------
-- SPRING CURVES
--------------------------------------------------------------------------------

-- Main spring
hl.curve("smoothSpring", {
    type = "spring",
    mass = 1.0,
    stiffness = 380,
    dampening = 30,
})

-- Slightly playful spring
hl.curve("playfulSpring", {
    type = "spring",
    mass = 1.0,
    stiffness = 430,
    dampening = 28,
})

hl.curve("special_smooth", {
    type = "bezier",
    points = {
        { 0.22, 1.0 },
        { 0.36, 1.0 },
    },
})

--------------------------------------------------------------------------------
-- GLOBAL
--------------------------------------------------------------------------------

hl.animation({
    leaf = "global",
    enabled = true,
    speed = speed_normal,
    bezier = "smooth",
})

--------------------------------------------------------------------------------
