    leaf = "windowsIn",
    enabled = true,
    speed = speed_fast,
    spring = "playfulSpring",
    style = "popin 85%",
})

-- Window closing
hl.animation({
    leaf = "windowsOut",
    enabled = true,
    speed = speed_out,
    bezier = "quick",
    style = "popin 85%",
})

hl.animation({
    leaf = "specialWorkspaceIn",
